								row, _ := control.(map[string]any)
								if row["name"] == "Skip field" {
									token, _ = row["value"].(string)
								}
							}
							p.mu.Unlock()
							if token != "" {
								break
							}
							more := waitObjectMessageControl(t, p, receipt, "More choices")
